// The page fee-waivers-inbox: Fee waivers to approve. It lists fee
// waivers to approve through listFeeWaivers, a page at a time, and runs
// approveFeeWaiver on a row.

import {
  on, emit,
  FEE_WAIVERS_INBOX_FILTERED, FEE_WAIVERS_INBOX_PAGED, FEE_WAIVERS_INBOX_LOADED, FEE_WAIVERS_INBOX_FAILED,
  APPROVE_FEE_WAIVER_SUCCEEDED, APPROVE_FEE_WAIVER_FAILED,
} from "./events.js";

const columns = ["loanId", "amount", "reason"];
const pageSize = 20;

const messages = {
  empty: "No request waits for approval.",
  filteredEmpty: "Nothing matches these filters.",
  failed: "This cannot be done right now. Try again in a moment.",
};

// What each operation's refusals say, by status: the page's failed states.
const refusals = {
  listFeeWaivers: {},
  approveFeeWaiver: {},
};

const actions = [
  {
    label: "Approve",
    operation: "approveFeeWaiver",
    method: "POST",
    path: (row) => `/fee-waivers/${encodeURIComponent(row.id)}/approve`,
    confirm: "Approve waiving this fee?",
    message: "The request is approved and the fee is waived.",
    succeeded: APPROVE_FEE_WAIVER_SUCCEEDED,
    failed: APPROVE_FEE_WAIVER_FAILED,
  },
];

/** The message of a refusal of an operation, or the page's default. */
function refusal(operation, status) {
  return refusals[operation][String(status)] ?? messages.failed;
}

/** Reads the list: the filters given, then the page. Only the answer to
    the latest request counts, and a page becomes the list's page once it
    has arrived. */
function loader() {
  let filters = {};
  let page = 1;
  let latest = 0;
  async function load(wanted) {
    const ask = ++latest;
    const query = new URLSearchParams();
    for (const [name, value] of Object.entries(filters)) {
      if (value !== "") {
        query.set(name, value);
      }
    }
    const filtered = [...query.keys()].length > 0;
    query.set("page", String(wanted));
    query.set("pageSize", String(pageSize));
    try {
      const response = await fetch(`/fee-waivers?${query}`, { headers: { Accept: "application/json" } });
      if (ask !== latest) {
        return;
      }
      if (!response.ok) {
        emit(FEE_WAIVERS_INBOX_FAILED, { status: response.status });
        return;
      }
      const body = await response.json();
      if (ask !== latest) {
        return;
      }
      if (body.items.length === 0 && wanted > 1 && body.totalPages > 0 && wanted > body.totalPages) {
        load(body.totalPages); // the page asked for is past the last
        return;
      }
      page = wanted;
      emit(FEE_WAIVERS_INBOX_LOADED, { items: body.items, totalItems: body.totalItems, totalPages: body.totalPages, page, filtered });
    } catch {
      if (ask === latest) {
        emit(FEE_WAIVERS_INBOX_FAILED, { status: 0 });
      }
    }
  }
  on(FEE_WAIVERS_INBOX_FILTERED, (payload) => {
    filters = payload;
    load(1);
  });
  on(FEE_WAIVERS_INBOX_PAGED, (payload) => load(payload.page));
  for (const action of actions) {
    on(action.succeeded, () => load(page));
  }
  load(1);
}

/** Runs an action on a row, once the person confirms it, its button
    disabled while it runs. */
async function run(action, row, button) {
  if (!window.confirm(action.confirm)) {
    return;
  }
  button.disabled = true;
  try {
    const response = await fetch(action.path(row), { method: action.method, headers: { Accept: "application/json" } });
    if (response.ok) {
      emit(action.succeeded, { id: row.id });
    } else {
      button.disabled = false;
      emit(action.failed, { id: row.id, status: response.status });
    }
  } catch {
    button.disabled = false;
    emit(action.failed, { id: row.id, status: 0 });
  }
}

/** The table of fee waivers to approve. Focus in it stays on the same button, or moves
    to the table when its row is gone. */
function table() {
  const body = document.querySelector("#rows tbody");
  const head = document.querySelectorAll("#rows thead th");
  on(FEE_WAIVERS_INBOX_LOADED, ({ items }) => {
    const focused = body.contains(document.activeElement) ? document.activeElement.dataset.key : undefined;
    body.replaceChildren();
    for (const row of items) {
      const tr = document.createElement("tr");
      columns.forEach((name, i) => {
        const td = document.createElement("td");
        td.className = head[i].className;
        td.textContent = row[name] ?? "";
        tr.append(td);
      });
      const cell = document.createElement("td");
      for (const action of actions) {
        const button = document.createElement("button");
        button.type = "button";
        button.textContent = action.label;
        button.setAttribute("aria-label", `${action.label} ${row[columns[0]] ?? ""}`.trim());
        button.dataset.key = `${action.operation} ${row.id}`;
        button.addEventListener("click", () => run(action, row, button));
        cell.append(button);
      }
      tr.append(cell);
      body.append(tr);
    }
    if (focused !== undefined) {
      const again = [...body.querySelectorAll("button")].find((button) => button.dataset.key === focused);
      (again ?? document.getElementById("rows")).focus();
    }
  });
}

/** The status line: states and the messages of events, announced without moving focus. */
function statusLine() {
  const line = document.getElementById("status");
  // An event's message stays until the person filters or pages; a state
  // gives way to the list it describes.
  let kept = false;
  function show(text, failed, keep) {
    line.textContent = text;
    line.classList.toggle("failed", failed);
    kept = keep;
  }
  on(FEE_WAIVERS_INBOX_FILTERED, () => show("", false, false));
  on(FEE_WAIVERS_INBOX_PAGED, () => show("", false, false));
  on(FEE_WAIVERS_INBOX_LOADED, ({ items, filtered }) => {
    if (kept) {
      return;
    }
    show(items.length === 0 ? (filtered ? messages.filteredEmpty : messages.empty) : "", false, false);
  });
  on(FEE_WAIVERS_INBOX_FAILED, ({ status }) => show(refusal("listFeeWaivers", status), true, false));
  for (const action of actions) {
    on(action.succeeded, () => show(action.message, false, true));
    on(action.failed, ({ status }) => show(refusal(action.operation, status), true, true));
  }
}

/** The pager. A button that is disabled while it has focus hands focus on. */
function pager() {
  const nav = document.getElementById("pager");
  const where = nav.querySelector("span");
  const [previous, next] = nav.querySelectorAll("button");
  let page = 1;
  on(FEE_WAIVERS_INBOX_LOADED, (payload) => {
    page = payload.page;
    where.textContent = `Page ${payload.page} of ${Math.max(payload.totalPages, 1)}`;
    const focused = document.activeElement;
    previous.disabled = payload.page <= 1;
    next.disabled = payload.page >= payload.totalPages;
    if (focused instanceof HTMLButtonElement && nav.contains(focused) && focused.disabled) {
      const other = focused === previous ? next : previous;
      (other.disabled ? document.getElementById("rows") : other).focus();
    }
  });
  for (const button of [previous, next]) {
    button.addEventListener("click", () => emit(FEE_WAIVERS_INBOX_PAGED, { page: page + Number(button.dataset.step) }));
  }
}

table();
statusLine();
pager();
loader();
